INSERT INTO Papers VALUES(5,'This study investigates explainable artificial intelligence techniques for improving the interpretability of deep learning models used in medical image classification.','Explainable AI, Deep Learning, Healthcare',NULL,'Accepted','2026-09-02 00:00:00','Explainable Deep Learning for Medical Diagnosis',6);
INSERT INTO Papers VALUES(6,'This research examines federated learning architectures that enable collaborative machine learning across healthcare institutions without sharing sensitive patient data.','Federated Learning, Privacy, Healthcare',NULL,'Under Review','2026-09-05 00:00:00','Federated Learning for Privacy-Preserving Healthcare',6);
INSERT INTO Papers VALUES(7,'This paper evaluates zero-trust security architectures for protecting distributed cloud environments against unauthorized access and lateral movement.','Zero Trust, Cloud Security, Cybersecurity',NULL,'Accepted','2026-09-08 00:00:00','Zero-Trust Security in Cloud Infrastructure',8);
INSERT INTO Papers VALUES(8,'This study compares supervised machine learning algorithms for detecting malicious network activity using network traffic features.','Intrusion Detection, Machine Learning, Network Security',NULL,'Under Review','2026-09-10 00:00:00','Machine Learning Approaches to Intrusion Detection',8);
INSERT INTO Papers VALUES(9,'This research explores transaction scheduling and concurrency control techniques to improve throughput and consistency in distributed database systems.','Distributed Systems, Databases, Transactions',NULL,'Submitted','2026-09-12 00:00:00','Optimizing Distributed Database Transactions',7);
INSERT INTO Papers VALUES(10,'This paper proposes workload scheduling strategies that reduce energy consumption while maintaining performance in cloud computing environments.','Cloud Computing, Scheduling, Energy Efficiency',NULL,'Accepted','2026-09-15 00:00:00','Energy-Efficient Scheduling in Cloud Computing',7);
INSERT INTO Papers VALUES(11,'This study applies statistical learning and time-series forecasting to predict traffic congestion and improve urban transportation planning.','Predictive Analytics, Transportation, Time Series',NULL,'Under Review','2026-09-18 00:00:00','Predictive Analytics for Urban Transportation',9);
INSERT INTO Papers VALUES(12,'This research investigates graph neural network models for identifying suspicious transaction patterns in financial networks.','Graph Neural Networks, Fraud Detection, Data Science',NULL,'Rejected','2026-09-20 00:00:00','Detecting Financial Fraud Using Graph Neural Networks',9);
INSERT INTO Papers VALUES(13,'This paper explores the use of large language models to automatically generate unit tests and identify potential software defects.','Software Testing, Large Language Models, Automation',NULL,'Accepted','2026-09-22 00:00:00','Automated Software Testing Using Large Language Models',10);
INSERT INTO Papers VALUES(14,'This study evaluates static analysis techniques for identifying maintainability issues and security vulnerabilities during software code review.','Static Analysis, Code Review, Software Quality',NULL,'Submitted','2026-09-25 00:00:00','Improving Code Review Through Static Analysis',10);
