INSERT INTO Reviews VALUES(4,'Excellent contribution to explainable AI. The methodology is well structured and the experimental results are convincing.',5,'2026-10-01 00:00:00','Dr. Robert Miller',5);
INSERT INTO Reviews VALUES(5,'Strong motivation and promising results. Additional evaluation across heterogeneous healthcare datasets would strengthen the paper.',6,'2026-10-03 00:00:00','Dr. Jennifer Adams',4);
INSERT INTO Reviews VALUES(6,'A thorough analysis of zero-trust architectures with practical recommendations for cloud infrastructure security.',7,'2026-10-04 00:00:00','Dr. Christopher Davis',5);
